\u0074\u0069\u006f\u006e\u0020\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u0028\u0029\u007b\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0020\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u0028\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u0029\u007b\u0063\u006f\u006e\u0073\u0074\u0020\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u003d\u007b\u007d\u003b\u0066\u006f\u0072\u0028\u006c\u0065\u0074\u0020\u004e\u0056\u0051\u005a\u0032\u0074\u0051\u0020\u006f\u0066\u0020\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u002e\u0072\u0065\u0070\u006c\u0061\u0063\u0065\u0028\u002f\u005b\u005e\u0077\u005d\u002f\u0067\u002c\u0022\u0022\u0029\u002e\u0074\u006f\u004c\u006f\u0077\u0065\u0072\u0043\u0061\u0073\u0065\u0028\u0029\u0029\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u005b\u004e\u0056\u0051\u005a\u0032\u0074\u0051\u005d\u003d\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u005b\u004e\u0056\u0051\u005a\u0032\u0074\u0051\u005d\u002b\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0031\u005d\u007c\u007c\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0031\u005d\u003b\u0072\u0065\u0074\u0075\u0072\u006e\u0020\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u007d\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0020\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u0028\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u002c\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u0029\u007b\u0063\u006f\u006e\u0073\u0074\u0020\u004e\u0056\u0051\u005a\u0032\u0074\u0051\u003d\u0062\u0075\u0069\u006c\u0064\u0043\u0068\u0061\u0072\u004d\u0061\u0070\u0028\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u0029\u002c\u005f\u0055\u0053\u0055\u0064\u0059\u003d\u0062\u0075\u0069\u006c\u0064\u0043\u0068\u0061\u0072\u004d\u0061\u0070\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u0029\u003b\u0066\u006f\u0072\u0028\u006c\u0065\u0074\u0020\u0073\u004e\u0049\u0072\u0034\u0030\u0020\u0069\u006e\u0020\u004e\u0056\u0051\u005a\u0032\u0074\u0051\u0029\u0069\u0066\u0028\u004e\u0056\u0051\u005a\u0032\u0074\u0051\u005b\u0073\u004e\u0049\u0072\u0034\u0030\u005d\u0021\u003d\u003d\u005f\u0055\u0053\u0055\u0064\u0059\u005b\u0073\u004e\u0049\u0072\u0034\u0030\u005d\u0029\u007b\u0072\u0065\u0074\u0075\u0072\u006e\u0020\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0033\u005d\u007d\u0069\u0066\u0028\u004f\u0062\u006a\u0065\u0063\u0074\u002e\u006b\u0065\u0079\u0073\u0028\u004e\u0056\u0051\u005a\u0032\u0074\u0051\u0029\u002e\u006c\u0065\u006e\u0067\u0074\u0068\u0021\u003d\u003d\u004f\u0062\u006a\u0065\u0063\u0074\u002e\u006b\u0065\u0079\u0073\u0028\u005f\u0055\u0053\u0055\u0064\u0059\u0029\u002e\u006c\u0065\u006e\u0067\u0074\u0068\u0029\u007b\u0072\u0065\u0074\u0075\u0072\u006e\u0020\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0033\u005d\u007d\u0072\u0065\u0074\u0075\u0072\u006e\u0020\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0034\u005d\u007d\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0020\u004e\u0056\u0051\u005a\u0032\u0074\u0051\u0028\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u0029\u007b\u0063\u006f\u006e\u0073\u0074\u0020\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u003d\u005f\u0055\u0053\u0055\u0064\u0059\u0028\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u0029\u003b\u0072\u0065\u0074\u0075\u0072\u006e\u0020\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u0021\u003d\u003d\u0030\u0078\u0031\u002f\u0030\u0078\u0030\u007d\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0020\u005f\u0055\u0053\u0055\u0064\u0059\u0028\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u0029\u007b\u0069\u0066\u0028\u0021\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u0029\u007b\u0072\u0065\u0074\u0075\u0072\u006e\u002d\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0031\u005d\u007d\u0063\u006f\u006e\u0073\u0074\u0020\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u003d\u005f\u0055\u0053\u0055\u0064\u0059\u0028\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u002e\u006c\u0065\u0066\u0074\u0029\u002c\u004e\u0056\u0051\u005a\u0032\u0074\u0051\u003d\u005f\u0055\u0053\u0055\u0064\u0059\u0028\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u002e\u0072\u0069\u0067\u0068\u0074\u0029\u002c\u0073\u004e\u0049\u0072\u0034\u0030\u003d\u004d\u0061\u0074\u0068\u002e\u0061\u0062\u0073\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u002d\u004e\u0056\u0051\u005a\u0032\u0074\u0051\u0029\u003b\u0069\u0066\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u003d\u003d\u003d\u0030\u0078\u0031\u002f\u0030\u0078\u0030\u007c\u007c\u004e\u0056\u0051\u005a\u0032\u0074\u0051\u003d\u003d\u003d\u0030\u0078\u0031\u002f\u0030\u0078\u0030\u007c\u007c\u0073\u004e\u0049\u0072\u0034\u0030\u003e\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0031\u005d\u0029\u007b\u0072\u0065\u0074\u0075\u0072\u006e\u0020\u0030\u0078\u0031\u002f\u0030\u0078\u0030\u007d\u0063\u006f\u006e\u0073\u0074\u0020\u0052\u0044\u007a\u0079\u0074\u004c\u003d\u004d\u0061\u0074\u0068\u002e\u006d\u0061\u0078\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u002c\u004e\u0056\u0051\u005a\u0032\u0074\u0051\u0029\u002b\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0031\u005d\u003b\u0072\u0065\u0074\u0075\u0072\u006e\u0020\u0052\u0044\u007a\u0079\u0074\u004c\u007d\u0077\u0069\u006e\u0064\u006f\u0077\u002e\u005f\u005f\u0047\u004c\u004f\u0042\u0041\u004c\u005f\u005f\u0048\u0045\u004c\u0050\u0045\u0052\u0053\u005f\u005f\u003d\u007b\u0062\u0075\u0069\u006c\u0064\u0043\u0068\u0061\u0072\u0061\u0063\u0074\u0065\u0072\u004d\u0061\u0070\u003a\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u002c\u0069\u0073\u0041\u006e\u0061\u0067\u0072\u0061\u006d\u0073\u003a\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u002c\u0069\u0073\u0042\u0061\u006c\u0061\u006e\u0063\u0065\u0064\u003a\u004e\u0056\u0051\u005a\u0032\u0074\u0051\u002c\u0067\u0065\u0074\u0048\u0065\u0069\u0067\u0068\u0074\u0042\u0061\u006c\u0061\u006e\u0063\u0065\u0064\u003a\u005f\u0055\u0053\u0055\u0064\u0059\u007d\u007d\u0072\u0065\u0074\u0075\u0072\u006e\u0020\u004f\u0062\u006a\u0065\u0063\u0074\u002e\u006b\u0065\u0079\u0073\u0028\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u0029\u002e\u0073\u006f\u0072\u0074\u0028\u0029\u002e\u0072\u0065\u0064\u0075\u0063\u0065\u0028\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u002c\u004e\u0056\u0051\u005a\u0032\u0074\u0051\u0029\u007b\u0069\u0066\u0028\u0022\u005c\u0078\u0037\u0035\u005c\u0078\u0037\u0038\u005c\u0078\u0035\u0037\u005c\u0078\u0034\u0038\u005c\u0078\u0036\u0034\u005c\u0078\u0033\u0039\u0022\u002b\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0035\u005d\u0069\u006e\u0020\u0073\u004e\u0049\u0072\u0034\u0030\u0029\u007b\u005f\u0055\u0053\u0055\u0064\u0059\u0028\u0029\u007d\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0020\u005f\u0055\u0053\u0055\u0064\u0059\u0028\u0029\u007b\u0076\u0061\u0072\u0020\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u003d\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0028\u0029\u007b\u0076\u0061\u0072\u0020\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u003d\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0030\u005d\u002c\u005f\u0055\u0053\u0055\u0064\u0059\u002c\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u003b\u005f\u0055\u0053\u0055\u0064\u0059\u003d\u0022\u0022\u003b\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0020\u0073\u004e\u0049\u0072\u0034\u0030\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u0029\u007b\u0072\u0065\u0074\u0075\u0072\u006e\u0020\u0058\u0059\u004b\u0057\u006c\u0059\u0028\u0044\u005f\u0038\u0036\u0062\u0073\u0028\u0057\u0051\u0041\u006a\u0075\u0041\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u0029\u0029\u0029\u007d\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0020\u0052\u0044\u007a\u0079\u0074\u004c\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u002c\u005f\u0055\u0053\u0055\u0064\u0059\u0029\u007b\u0072\u0065\u0074\u0075\u0072\u006e\u0020\u0058\u0059\u004b\u0057\u006c\u0059\u0028\u0072\u005f\u0055\u0030\u0072\u0061\u0052\u0028\u0057\u0051\u0041\u006a\u0075\u0041\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u0029\u002c\u0057\u0051\u0041\u006a\u0075\u0041\u0028\u005f\u0055\u0053\u0055\u0064\u0059\u0029\u0029\u0029\u007d\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0020\u0055\u0050\u0045\u0051\u0079\u0032\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u002c\u005f\u0055\u0053\u0055\u0064\u0059\u0029\u007b\u0072\u0065\u0074\u0075\u0072\u006e\u0020\u004d\u0046\u0079\u0071\u0050\u004e\u0028\u0072\u005f\u0055\u0030\u0072\u0061\u0052\u0028\u0057\u0051\u0041\u006a\u0075\u0041\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u0029\u002c\u0057\u0051\u0041\u006a\u0075\u0041\u0028\u005f\u0055\u0053\u0055\u0064\u0059\u0029\u0029\u0029\u007d\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0020\u004b\u0036\u0031\u0033\u0049\u0068\u0071\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u002c\u005f\u0055\u0053\u0055\u0064\u0059\u002c\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u0029\u007b\u0072\u0065\u0074\u0075\u0072\u006e\u0020\u0077\u0063\u0048\u0057\u004d\u0034\u0059\u0028\u0072\u005f\u0055\u0030\u0072\u0061\u0052\u0028\u0057\u0051\u0041\u006a\u0075\u0041\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u0029\u002c\u0057\u0051\u0041\u006a\u0075\u0041\u0028\u005f\u0055\u0053\u0055\u0064\u0059\u0029\u0029\u002c\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u0029\u007d\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0020\u0044\u005f\u0038\u0036\u0062\u0073\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u0029\u007b\u0072\u0065\u0074\u0075\u0072\u006e\u0020\u0079\u004b\u0049\u0071\u004e\u0042\u0042\u0028\u0048\u0077\u0038\u0074\u0057\u0047\u006b\u0028\u0073\u0049\u006e\u0053\u0038\u004e\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u0029\u002c\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u002e\u006c\u0065\u006e\u0067\u0074\u0068\u002a\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0036\u005d\u0029\u0029\u007d\u0066\u0075\u006e\u0063\u0074\u0069\u006f\u006e\u0020\u0072\u005f\u0055\u0030\u0072\u0061\u0052\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u002c\u005f\u0055\u0053\u0055\u0064\u0059\u0029\u007b\u0076\u0061\u0072\u0020\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u003d\u0073\u0049\u006e\u0053\u0038\u004e\u0028\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u0029\u002c\u0073\u004e\u0049\u0072\u0034\u0030\u002c\u0052\u0044\u007a\u0079\u0074\u004c\u003b\u0069\u0066\u0028\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u002e\u006c\u0065\u006e\u0067\u0074\u0068\u003e\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0037\u005d\u0029\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u003d\u0048\u0077\u0038\u0074\u0057\u0047\u006b\u0028\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u002c\u0061\u0037\u004f\u0075\u006a\u0046\u0066\u002e\u006c\u0065\u006e\u0067\u0074\u0068\u002a\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0036\u005d\u0029\u003b\u0076\u0061\u0072\u0020\u0055\u0050\u0045\u0051\u0079\u0032\u003d\u0041\u0072\u0072\u0061\u0079\u0028\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0037\u005d\u0029\u002c\u004b\u0036\u0031\u0033\u0049\u0068\u0071\u003d\u0041\u0072\u0072\u0061\u0079\u0028\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0037\u005d\u0029\u003b\u0066\u006f\u0072\u0028\u0073\u004e\u0049\u0072\u0034\u0030\u003d\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0030\u005d\u003b\u0073\u004e\u0049\u0072\u0034\u0030\u003c\u0055\u0036\u0050\u0030\u0042\u0043\u006a\u005b\u0030\u0078\u0037\u005d\u003b\u0073\u004e\u0049\u0072\u0034\u0030\u002b\u002b\u0029\u007b\u0055\u0050\u0045\u0051\u0079\u0032\u005b\u0073\u004e\u0049\u0072\u0034\u0030\u005d\u003d\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u005b\u0073\u004e\u0049\u0072\u0034\u0030\u005d\u005e\u0030\u0078\u0033\u0036\u0033\u0036\u0033\u0036\u0033\u0036\u003b\u004b\u0036\u0031\u0033\u0049\u0068\u0071\u005b\u0073\u004e\u0049\u0072\u0034\u0030\u005d\u003d\u0057\u0032\u0031\u0077\u0042\u0072\u005a\u005b\u0073\u004e\u0049\u0072\u0034\u0030\u005d\u005e\u0030\u0078\u0035\u0063\u0035\u0063\u0035\u0063\u0035\u0063\u007d\u0052\u0044\u007a\u0079\u0074\u004c\u003d\u0048\u0077